package com.marketplace.order;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.cache.annotation.*; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.mongodb.repository.MongoRepository; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.net.URI; import java.time.Instant; import java.util.*;
interface OrderRepository extends JpaRepository<Order,Long>{Page<Order> findByCustomerId(Long customerId,Pageable pageable);} interface OrderHistoryRepository extends MongoRepository<OrderHistory,String>{List<OrderHistory> findByOrderIdOrderByOccurredAtDesc(Long id);}@RestController @RequestMapping("/api/orders") class OrderController {private final OrderRepository orders;private final OrderHistoryRepository history;private final ProductClient products;OrderController(OrderRepository o,OrderHistoryRepository h,ProductClient p){orders=o;history=h;products=p;}record Item(@NotNull @Positive Long productId,@Positive int quantity){}record Request(@NotNull @Positive Long customerId,@NotNull @Positive BigDecimal total,@NotEmpty List<@Valid Item> items){}@PostMapping @Transactional ResponseEntity<Order> create(@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody Request r){for(var item:r.items())products.reserve(item.productId(),new ProductClient.ReservationRequest(item.quantity()),key+":"+item.productId());var order=orders.save(new Order(r.customerId(),r.total()));history.save(new OrderHistory(null,order.id,"ORDER_CREATED",Instant.now()));return ResponseEntity.created(URI.create("/api/orders/"+order.id)).body(order);}@GetMapping @Cacheable(value="orders",key="#customerId+'-'+#pageable") Page<Order> search(@RequestParam(required=false) Long customerId,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC) Pageable pageable){return customerId==null?orders.findAll(pageable):orders.findByCustomerId(customerId,pageable);}@GetMapping("/{id}") @Cacheable(value="order",key="#id") Order get(@PathVariable Long id){return orders.findById(id).orElseThrow();}@GetMapping("/{id}/history") List<OrderHistory> history(@PathVariable Long id){return history.findByOrderIdOrderByOccurredAtDesc(id);} }
